# Vertragszeitraum, Beantragung, Ausstieg und Übernahme (Informationsblatt Kap. 3.1, 7, 8;
# Allgemeine Teilnahmebedingungen 5.8, 5.9, 6, 6.3; SRL 1.7.1.1, 1.7.3.1, 1.10.5).
package oepul.o6_20.application

import data.oepul.o6_20.common

params := common.params

gc := data.o6_20.general_conditions

tw := common.tw

year := common.year

# --- Einstieg / Vertragsbeginn ---------------------------------------------

new_entry if object.get(tw, "participation_start_year", year) == year

entry_year_allowed if year <= params.last_entry_funding_year

violations contains v if {
	new_entry
	not entry_year_allowed
	v := {
		"rule_id": "o6_20.application.last_entry",
		"severity": "contract_invalid",
		"message": sprintf("Einstieg für Förderjahr %d nicht mehr möglich (letzter Einstieg Förderjahr %d)", [year, params.last_entry_funding_year]),
	}
}

# Auch der Einstieg in einzelne Kategorien ist letztmals mit dem Förderjahr 2027 möglich.
violations contains v if {
	some c in common.categories
	object.get(c, "first_year", object.get(tw, "participation_start_year", year)) > params.last_entry_funding_year
	v := {
		"rule_id": "o6_20.application.last_entry",
		"severity": "category_invalid",
		"category_code": c.category_code,
		"message": sprintf("Einstieg in die Kategorie nach Förderjahr %d nicht möglich", [params.last_entry_funding_year]),
	}
}

application_in_time(d, funding_year) if {
	common.is_date(d)
	d <= common.measure_application_deadline(funding_year)
}

violations contains v if {
	new_entry
	not application_in_time(object.get(tw, "measure_application_date", null), year)
	v := {
		"rule_id": "o6_20.application.measure_application_deadline",
		"severity": "contract_invalid",
		"message": sprintf("Maßnahmenantrag nicht bis %v gestellt", [common.measure_application_deadline(year)]),
	}
}

# Neu hinzukommende Kategorien benötigen ebenfalls einen Maßnahmenantrag bis 31.12. des Vorjahres.
violations contains v if {
	some c in common.categories
	object.get(c, "first_year", object.get(tw, "participation_start_year", year)) == year
	not new_entry
	not application_in_time(object.get(c, "application_date", null), year)
	not late_reapplication_accepted(c)
	v := {
		"rule_id": "o6_20.application.measure_application_deadline",
		"severity": "category_invalid",
		"category_code": c.category_code,
		"message": sprintf("Kategorie nicht bis %v im Maßnahmenantrag beantragt", [common.measure_application_deadline(year)]),
	}
}

# Nach Erlöschen einer Kategorie: Neubeantragung, verspätet nur mit Korrektur und schriftlichem Ersuchen.
late_reapplication_accepted(c) if {
	object.get(c, "reapplied_by_correction", false) == true
	object.get(c, "written_request_submitted", false) == true
}

violations contains v if {
	some c in common.categories
	object.get(c, "contract_lapsed_previous_year", false) == true
	not application_in_time(object.get(c, "application_date", null), year)
	not late_reapplication_accepted(c)
	v := {
		"rule_id": "o6_20.application.category_reentry",
		"severity": "category_invalid",
		"category_code": c.category_code,
		"message": "Vertrag der Kategorie im Vorjahr erloschen – neuer Maßnahmenantrag bzw. Korrektur samt schriftlichem Ersuchen erforderlich",
	}
}

# --- Optionaler Zuschlag 150 Weidetage -----------------------------------------

violations contains v if {
	some c in common.categories
	object.get(c, "supplement_150_applied", false) == true
	not supplement_application_in_time(c)
	v := {
		"rule_id": "o6_20.application.supplement_150_deadline",
		"severity": "no_supplement",
		"category_code": c.category_code,
		"message": sprintf("Zuschlag 150 Weidetage nicht bis %v in der Beilage beantragt", [common.beilage_deadline(year)]),
	}
}

supplement_application_in_time(c) if {
	d := object.get(c, "supplement_150_application_date", null)
	common.is_date(d)
	d <= common.beilage_deadline(year)
}

violations contains v if {
	some c in common.categories
	object.get(c, "supplement_150_applied", false) == true
	year > params.last_supplement_funding_year
	v := {
		"rule_id": "o6_20.application.supplement_150_deadline",
		"severity": "no_supplement",
		"category_code": c.category_code,
		"message": "Zuschlag nur bis einschließlich Förderjahr 2028 beantragbar",
	}
}

# --- Schafe und Ziegen: Einzeltierbeantragung zum Stichtag 1. April ---------------

sheep_goat(a) if common.regime(a.category_code) == "sheep_goat"

violations contains v if {
	some a in common.animals
	common.sheep_goat_late_individual_application(a)
	v := {
		"rule_id": "o6_20.application.sheep_goat_individual",
		"severity": "no_premium",
		"category_code": a.category_code,
		"animal_id": a.animal_id,
		"message": sprintf("Einzeltierbeantragung nach Frist %v", [common.beilage_deadline(year)]),
	}
}

violations contains v if {
	some a in common.animals
	sheep_goat(a)
	some field in ["ear_tag", "sex", "birth_date"]
	not object.get(a, field, null)
	v := {
		"rule_id": "o6_20.application.sheep_goat_individual",
		"severity": "input_error",
		"category_code": a.category_code,
		"animal_id": a.animal_id,
		"message": sprintf("Einzeltierbeantragung ohne Angabe %s", [field]),
	}
}

# --- Equiden und Neuweltkamele: Stückzahl bis 15. April, danach keine Ausweitung --

violations contains v if {
	some c in common.categories
	common.regime(c.category_code) == "equid_camelid"
	some e in object.get(c, "count_entries", [])
	object.get(e, "count_increased_after_deadline", false) == true
	v := {
		"rule_id": "o6_20.application.equid_camelid_count",
		"severity": "no_premium",
		"category_code": c.category_code,
		"message": sprintf("Ausweitung der Stückzahl nach %v nicht zulässig", [common.beilage_deadline(year)]),
	}
}

# --- Ausstieg / Abmeldung ------------------------------------------------------

deregistered_in_year if {
	d := object.get(tw, "deregistration_date", null)
	common.is_date(d)
	d >= common.md_date(year, "01-01")
	d <= common.md_date(year, "12-31")
}

violations contains v if {
	deregistered_in_year
	v := {
		"rule_id": "o6_20.exit.deregistration",
		"severity": "contract_invalid",
		"message": "Abmeldung innerhalb des Förderjahres – Maßnahme im betroffenen Förderjahr nicht mehr gültig",
	}
}

category_deregistered_in_year(c) if {
	d := object.get(c, "deregistration_date", null)
	common.is_date(d)
	d >= common.md_date(year, "01-01")
	d <= common.md_date(year, "12-31")
}

violations contains v if {
	some c in common.categories
	category_deregistered_in_year(c)
	v := {
		"rule_id": "o6_20.exit.deregistration",
		"severity": "category_invalid",
		"category_code": c.category_code,
		"message": "Kategorie innerhalb des Förderjahres abgemeldet – für das Förderjahr nicht mehr gültig",
	}
}

review_items contains r if {
	some event in gc.exit_blocking_events
	object.get(tw, ["exit_context", event], false) == true
	object.get(tw, "deregistration_date", null) != null
	r := {
		"rule_id": "o6_20.exit.timing_controls",
		"message": sprintf("Ausstieg nur bis zur Durchführung/Ankündigung einer Vor-Ort-Kontrolle bzw. Mitteilung einer Verwaltungskontrolle möglich (%s)", [event]),
	}
}

# Ersetzte (ausgelaufene) Kategorie muss nach dem 31.12. abgemeldet werden, sonst gelten die Auflagen weiter.
violations contains v if {
	some c in common.categories
	object.get(c, "replaced_by_other_category", false) == true
	not common.is_date(object.get(c, "deregistration_date", null))
	v := {
		"rule_id": "o6_20.application.category_replacement",
		"severity": "obligation_continues",
		"category_code": c.category_code,
		"message": "Ersetzte Kategorie nicht abgemeldet – Maßnahme ist für alle gültigen Kategorien einzuhalten",
	}
}

# --- Maßnahmenübernahme ------------------------------------------------------

takeover := object.get(tw, "takeover", {})

violations contains v if {
	object.get(takeover, "is_takeover", false) == true
	not object.get(takeover, "reason", null) in gc.takeover_permitted_reasons
	v := {
		"rule_id": "o6_20.gen.takeover",
		"severity": "contract_invalid",
		"message": "Übernahme von „Tierwohl – Weide“ nur im Einzelfall bei Betriebsauflösung, -teilung oder -zusammenlegung",
	}
}

violations contains v if {
	object.get(takeover, "is_takeover", false) == true
	object.get(takeover, "animals_and_areas_from_same_previous_farm", true) == false
	v := {
		"rule_id": "o6_20.gen.takeover",
		"severity": "contract_invalid",
		"message": "Bei Übernahme tierbezogener Maßnahmen müssen Tiere und Flächen vom selben Vorbetrieb stammen",
	}
}

# --- Einjährige Maßnahme, automatische Verlängerung ------------------------------

one_year_measure if "Tierwohl – Weide" in gc.one_year_measures

auto_renewal := false if deregistered_in_year

else := true

contract_period := {
	"start": common.md_date(year, "01-01"),
	"end": common.md_date(year, "12-31"),
	"one_year_measure": one_year_measure,
	"auto_renewal": auto_renewal,
}

# Zugangs- und Teilnahmevoraussetzungen (Informationsblatt Kap. 3, 4; Allgemeine Teilnahmebedingungen 5.2, 5.3, 5.6; SRL 1.4, 1.6.1, 2.20.3).
package oepul.o6_20.eligibility

import data.oepul.o6_20.common
import data.oepul.o6_20.rgve

gc := data.o6_20.general_conditions

applicant := object.get(input, ["farm", "applicant"], {})

participation := object.get(input, ["farm", "oepul_participation"], {})

# --- Förderwerbende Personen -------------------------------------------------

applicant_form_eligible if applicant.legal_form in gc.eligible_applicant_forms

violations contains v if {
	applicant.legal_form
	not applicant_form_eligible
	v := {
		"rule_id": "o6_20.gen.applicant.legal_form",
		"severity": "contract_invalid",
		"message": sprintf("Rechtsform %v ist keine zulässige förderwerbende Person", [applicant.legal_form]),
	}
}

missing_inputs contains "farm.applicant.legal_form" if not applicant.legal_form

violations contains v if {
	some field in ["is_active_farmer", "has_agricultural_activity", "farms_in_own_name_and_account"]
	object.get(applicant, field, true) == false
	v := {
		"rule_id": "o6_20.gen.applicant.active_farmer",
		"severity": "contract_invalid",
		"message": sprintf("Voraussetzung nicht erfüllt: %s", [field]),
	}
}

# Gebietskörperschaften bzw. Beteiligung > 25 % sind grundsätzlich ausgeschlossen, außer bei
# den in data.o6_20.general_conditions.public_body_permitted_measures genannten Maßnahmen.
public_body_involved if object.get(applicant, "is_public_body", false) == true

public_body_involved if object.get(applicant, "public_body_share_percent", 0) > gc.public_body_max_share_percent

measure_permits_public_body(measure_key, y) if {
	some m in gc.public_body_permitted_measures
	m.measure_key == measure_key
	year_in_range(y, m.from_year, m.to_year)
}

year_in_range(y, from, to) if {
	from_ok(y, from)
	to_ok(y, to)
}

from_ok(_, from) if from == null

from_ok(y, from) if y >= from

to_ok(_, to) if to == null

to_ok(y, to) if y <= to

public_body_permitted if measure_permits_public_body(common.params.measure_key, common.year)

violations contains v if {
	public_body_involved
	not public_body_permitted
	v := {
		"rule_id": "o6_20.gen.applicant.public_body",
		"severity": "contract_invalid",
		"message": "Gebietskörperschaft bzw. bestimmender Einfluss einer Gebietskörperschaft: Maßnahme nicht zugänglich",
	}
}

# --- Betriebsmindestgröße im ersten ÖPUL-Teilnahmejahr ----------------------

first_oepul_year if common.year == participation.first_oepul_year

min_farm_size_met if {
	object.get(input, ["land", "protected_cultivation_area_ha"], 0) >= gc.min_farm_size_first_year.protected_cultivation_ha
}

min_farm_size_met if {
	object.get(input, ["land", "total_area_ha"], 0) >= gc.min_farm_size_first_year.agricultural_area_ha
}

violations contains v if {
	first_oepul_year
	not min_farm_size_met
	v := {
		"rule_id": "o6_20.gen.min_farm_size_first_year",
		"severity": "contract_invalid",
		"message": "Betriebsmindestgröße im ersten ÖPUL-Teilnahmejahr (1,50 ha bzw. 0,50 ha geschützter Anbau) nicht erreicht",
	}
}

missing_inputs contains "farm.oepul_participation.first_oepul_year" if not participation.first_oepul_year

# --- Mindestteilnahme 2,00 RGVE ---------------------------------------------

min_participation_met if rgve.total_rgve >= common.params.min_participation_rgve

violations contains v if {
	count(common.categories) > 0
	not min_participation_met
	v := {
		"rule_id": "o6_20.min_participation.rgve",
		"severity": "contract_invalid",
		"message": sprintf("Durchschnittlich %.2f RGVE im Weidezeitraum; mindestens %.2f RGVE über alle beantragten Kategorien erforderlich – Vertrag erlischt", [rgve.total_rgve, common.params.min_participation_rgve]),
	}
}

# --- Teilnahmefähige Tierkategorien -----------------------------------------

violations contains v if {
	some code in common.applied_category_codes
	not common.category_defs[code]
	v := {
		"rule_id": "o6_20.categories.closed_list",
		"severity": "category_invalid",
		"category_code": code,
		"message": sprintf("Tierkategorie %v ist in der Maßnahme nicht wählbar", [code]),
	}
}

violations contains v if {
	some code in common.duplicate_category_codes
	v := {
		"rule_id": "o6_20.categories.closed_list",
		"severity": "input_error",
		"category_code": code,
		"message": sprintf("Tierkategorie %v mehrfach angegeben", [code]),
	}
}

violations contains v if {
	some a in common.animals
	not rgve.class_allowed(a.category_code, a.rgve_class)
	v := {
		"rule_id": "o6_20.rgve.key",
		"severity": "no_premium",
		"category_code": a.category_code,
		"animal_id": a.animal_id,
		"message": sprintf("RGVE-Klasse %v ist für Kategorie %v nicht zulässig", [a.rgve_class, a.category_code]),
	}
}

violations contains v if {
	some c in common.categories
	some e in object.get(c, "count_entries", [])
	not rgve.class_allowed(c.category_code, e.rgve_class)
	v := {
		"rule_id": "o6_20.rgve.key",
		"severity": "no_premium",
		"category_code": c.category_code,
		"message": sprintf("RGVE-Klasse %v ist für Kategorie %v nicht zulässig", [e.rgve_class, c.category_code]),
	}
}

# --- Mindestteilnahme je Kategorie (Kap. 3.2) --------------------------------

supplement_applied(c) if object.get(c, "supplement_150_applied", false) == true

required_presence_days(c) := common.params.min_grazing_days_supplement if supplement_applied(c)

else := common.params.min_grazing_days_base

presence_ok(c) if object.get(c, "days_with_min_one_animal_present", 0) >= required_presence_days(c)

# Weibliche Rinder: beide Kategorien beantragt, ein konkretes Tier erreicht über beide Kategorien die Tage.
presence_ok(c) if {
	pair := common.catalog.female_cattle_category_pair
	c.category_code in pair
	every p in pair {
		p in common.applied_category_codes
	}
	object.get(c, "female_cattle_combined_single_animal_days", 0) >= required_presence_days(c)
}

violations contains v if {
	some c in common.categories
	common.category_defs[c.category_code]
	not presence_ok(c)
	v := {
		"rule_id": "o6_20.min_participation.category_presence",
		"severity": "category_invalid",
		"category_code": c.category_code,
		"message": sprintf("Kein Tier der Kategorie (auch nicht durch Ersatztiere) %d Tage im Weidezeitraum am Betrieb", [required_presence_days(c)]),
	}
}

# Ohne prämienfähiges Tier erlischt der Vertrag für die Kategorie (Kap. 7).
violations contains v if {
	some code in common.applied_category_codes
	common.category_defs[code]
	rgve.category_rgve(code) <= 0
	v := {
		"rule_id": "o6_20.application.category_lapse_no_animal",
		"severity": "category_invalid",
		"category_code": code,
		"message": "Kein prämienfähiges Tier in der Kategorie – Vertrag für die Kategorie erlischt",
	}
}

category_valid(code) if {
	common.category_defs[code]
	c := common.category_entry(code)
	presence_ok(c)
	rgve.category_rgve(code) > 0
}

# --- Haltungsort der Tiere --------------------------------------------------

violations contains v if {
	some a in common.animals
	object.get(a, "held_in_austria", true) == false
	v := {
		"rule_id": "o6_20.gen.animals_in_austria",
		"severity": "no_premium",
		"category_code": a.category_code,
		"animal_id": a.animal_id,
		"message": "Tier wird nicht in Österreich gehalten – nicht prämienfähig",
	}
}

# --- Betriebsstrukturwechsel bei Rindern ------------------------------------

review_items contains r if {
	some a in common.animals
	common.regime(a.category_code) == "cattle"
	common.is_date(object.get(a, "structure_change_date", null))
	r := {
		"rule_id": "o6_20.min_participation.structure_change_cattle",
		"animal_id": a.animal_id,
		"message": sprintf("Rind ab %v der neuen Betriebsstruktur zugerechnet; für die ursprüngliche Struktur nicht mehr prämienfähig", [a.structure_change_date]),
	}
}

# Allgemeine Bedingungen mit Relevanz für "Tierwohl – Weide" (Konditionalität, Kontrollen,
# Verpflichtungsdauer, Kombination; Allgemeine Teilnahmebedingungen 5.1, 5.8, 6.1, 8; SRL 1.7, 1.9.4, 1.11, 1.12).
package oepul.o6_20.general

import data.oepul.o6_20.common

participation := object.get(input, ["farm", "oepul_participation"], {})

tw := common.tw

# Konditionalität: Verstöße führen zu Kürzungen nach Art. 83–89 VO (EU) 2021/2116.
violations contains v if {
	object.get(participation, "conditionality_compliant", true) == false
	v := {
		"rule_id": "o6_20.gen.conditionality",
		"severity": "sanction_risk",
		"message": "Konditionalität bzw. soziale Konditionalität nicht eingehalten – Förderung nicht in voller Höhe",
	}
}

# Verweigerung/Verhinderung einer Vor-Ort-Kontrolle ohne höhere Gewalt: Ablehnung, Vertragsbeendigung.
violations contains v if {
	object.get(tw, ["control", "on_site_control_refused"], false) == true
	object.get(tw, "force_majeure_recognized", false) == false
	v := {
		"rule_id": "o6_20.gen.control_refusal",
		"severity": "contract_invalid",
		"message": "Vor-Ort-Kontrolle verweigert oder verhindert – Antrag abzulehnen, Verträge beendet und rückabgewickelt",
	}
}

# Förderverpflichtungen gelten während der gesamten Verpflichtungsdauer (Kalenderjahr); Tiere sind
# nur förderfähig, wenn sie gemäß den relevanten Bestimmungen gehalten werden.
violations contains v if {
	object.get(tw, "obligations_kept_whole_year", true) == false
	v := {
		"rule_id": "o6_20.gen.commitment_whole_year",
		"severity": "no_premium",
		"message": "Förderverpflichtungen nicht während der gesamten Verpflichtungsdauer (1.1.–31.12.) erfüllt",
	}
}

# Leistungsüberschneidung: dieselbe Leistung darf nicht aus anderem öffentlichen Titel gefördert sein.
violations contains v if {
	object.get(tw, "same_service_funded_elsewhere", false) == true
	v := {
		"rule_id": "o6_20.gen.double_funding",
		"severity": "no_premium",
		"message": "Leistung wird bereits aus einem anderen Titel der öffentlichen Hand gefördert bzw. ist gesetzlich vorgeschrieben",
	}
}

# Unmögliche Maßnahmenkombinationen können bis zur Auszahlungsmitteilung korrigiert werden.
review_items contains r if {
	some m in object.get(tw, "excluded_combinations_applied", [])
	r := {
		"rule_id": "o6_20.gen.combination",
		"message": sprintf("Nicht kombinierbare Maßnahme %v beantragt – Korrektur bis zum Erhalt der Auszahlungsmitteilung zulässig", [m]),
	}
}

# Jahresspezifische AMA-Hinweise 2026 mit Bezug zu "Tierwohl – Weide".
package oepul.o6_20.notices_2026

import data.oepul.o6_20.common

tw := common.tw

# Trockenheit 2026: Bei Vor-Ort-Kontrollen wird die besondere Situation u. a. hinsichtlich des
# Grundfutterbedarfs auf der Weide berücksichtigt (Hinweis vom 22.05.2026).
drought_consideration_applies if {
	common.year == 2026
	object.get(tw, "drought_affected_2026", false) == true
}

review_items contains r if {
	drought_consideration_applies
	some c in common.categories
	object.get(c, "forage_mainly_from_grazing", true) == false
	r := {
		"rule_id": "o6_20.notice2026.drought_forage_consideration",
		"category_code": c.category_code,
		"message": "Grundfutterbedarf nicht überwiegend über Beweidung gedeckt: Trockenheit 2026 wird bei Vor-Ort-Kontrollen berücksichtigt (Einzelfallbeurteilung)",
	}
}

# Höhere Gewalt (§ 6 GSP-AV, SRL 1.7.4.1): anerkannter Antrag schließt Sanktionen wegen
# nicht einhaltbarer Förderverpflichtungen aus.
force_majeure_recognized if object.get(tw, "force_majeure_recognized", false) == true

review_items contains r if {
	object.get(tw, "force_majeure_claimed", false) == true
	not force_majeure_recognized
	r := {
		"rule_id": "o6_20.notice2026.force_majeure_application",
